'use strict';

// MODULES //

// eslint-disable-next-line node/no-unpublished-require
var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var isNegativeZerof = require( '@stdlib/math/base/assert/is-negative-zerof' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var EPS = require( '@stdlib/constants/float32/eps' );
var abs = require( '@stdlib/math/base/special/abs' );
var truncbf = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof truncbf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function rounds a number toward zero to n digits in base 10', function test( t ) {
	var delta;
	var tol;
	var v;

	v = truncbf( 3.14159, 0, 10 );
	t.strictEqual( v, 3.0, 'equals expected value' );

	v = truncbf( 3.14159, 1, 10 );
	delta = abs( v - 3.1 );
	tol = EPS;
	t.ok( delta <= tol, 'equals expected value' );

	v = truncbf( 3.14159, 2, 10 );
	delta = abs( v - 3.14 );
	tol = EPS;
	t.ok( delta <= tol, 'equals expected value' );

	v = truncbf( 3.14159, 3, 10 );
	delta = abs( v - 3.141 );
	tol = EPS;
	t.ok( delta <= tol, 'equals expected value' );

	v = truncbf( 15.0, -1, 10 );
	t.strictEqual( v, 10.0, 'equals expected value' );

	v = truncbf( 158.0, -2, 10 );
	t.strictEqual( v, 100.0, 'equals expected value' );

	t.end();
});

tape( 'the function rounds negative numbers toward zero to n digits in base 10', function test( t ) {
	var delta;
	var tol;
	var v;

	v = truncbf( -3.14159, 0, 10 );
	t.strictEqual( v, -3.0, 'equals expected value' );

	v = truncbf( -3.14159, 1, 10 );
	delta = abs( v - (-3.1) );
	tol = EPS;
	t.ok( delta <= tol, 'equals expected value' );

	v = truncbf( -3.14159, 2, 10 );
	delta = abs( v - (-3.14) );
	tol = EPS;
	t.ok( delta <= tol, 'equals expected value' );

	v = truncbf( -15.0, -1, 10 );
	t.strictEqual( v, -10.0, 'equals expected value' );

	t.end();
});

tape( 'the function rounds a number toward zero to n digits in base 2', function test( t ) {
	var v;

	v = truncbf( 5.5, 0, 2 );
	t.strictEqual( v, 5.0, 'equals expected value' );

	v = truncbf( 7.5, 0, 2 );
	t.strictEqual( v, 7.0, 'equals expected value' );

	v = truncbf( 7.75, 1, 2 );
	t.strictEqual( v, 7.5, 'equals expected value' );

	t.end();
});

tape( 'the function returns NaN if provided NaN', function test( t ) {
	var v = truncbf( NaN, 2, 10 );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns NaN if provided a base of 0', function test( t ) {
	var v = truncbf( 3.14, 2, 0 );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns +0 if provided +0', function test( t ) {
	var v = truncbf( 0.0, 2, 10 );
	t.strictEqual( isPositiveZerof( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns -0 if provided -0', function test( t ) {
	var v = truncbf( -0.0, 2, 10 );
	t.strictEqual( isNegativeZerof( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns +infinity if provided +infinity', function test( t ) {
	var v = truncbf( PINF, 2, 10 );
	t.strictEqual( v, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns -infinity if provided -infinity', function test( t ) {
	var v = truncbf( NINF, 2, 10 );
	t.strictEqual( v, NINF, 'returns expected value' );
	t.end();
});

tape( 'the function handles scale factor overflow gracefully', function test( t ) {
	var v;

	// When b^n overflows to Infinity, should return x unchanged
	v = truncbf( 3.14, 40, 10 );
	t.strictEqual( v, float64ToFloat32( 3.14 ), 'handles large exponent' );

	v = truncbf( -2.5, 50, 10 );
	t.strictEqual( v, float64ToFloat32( -2.5 ), 'handles large exponent with negative x' );

	t.end();
});
